-- Daily product-suggestion e-mail (RECOMMENDATION_DIGEST_JOB).
-- 1. Every existing user receives it (owner's decision, 2026-11-07) until they unsubscribe.
--    The unsubscribe token is generated by the job on the first e-mail sent to the user.
-- 2. recommendationTable records each product sent (generatedAt = send date). Created here if
--    the database was built without it (it was not in databaseSchemaInitFile.sql).
START TRANSACTION;

ALTER TABLE userTable
    ADD COLUMN recommendationEmailEnabled BOOLEAN NOT NULL DEFAULT TRUE,
    ADD COLUMN recommendationEmailUnsubscribeToken BINARY(16) NULL UNIQUE;

CREATE TABLE IF NOT EXISTS recommendationTable
(
    id          BIGINT     NOT NULL AUTO_INCREMENT,
    uuid        BINARY(16) NOT NULL UNIQUE,
    version     BIGINT     NOT NULL,
    createdAt   DATETIME   NOT NULL,
    updatedAt   DATETIME,

    userId      BIGINT     NOT NULL,
    productId   BIGINT     NOT NULL,
    score       DOUBLE     NOT NULL,
    generatedAt DATETIME   NOT NULL,

    PRIMARY KEY (id),
    INDEX idx_recommendation_user_generated (userId, generatedAt),
    FOREIGN KEY (userId) REFERENCES userTable (id),
    FOREIGN KEY (productId) REFERENCES productTable (id)
);

COMMIT;
